// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(1000);
        vm.deal(address(this), 20 ether);
        vm.prank(address(this));
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "First call failed");

        vm.warp(1000);
        vm.prank(address(this));
        (bool success2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!success2, "Second call should have reverted on reference");
    }
}
